"use client";

import { useCallback, useEffect, useId, useRef, useState, type ChangeEvent, type ComponentProps, type FocusEvent } from "react";

import { IconAlertCircle } from "@rhs-ui/icons";
import { trackPress, whenReleased } from "@rhs-ui/primitives/email-field/blur-guard";
import { DEFAULT_EMAIL_DOMAINS, describeEmail, isValidEmail, normalizeEmail, suggestEmail } from "@rhs-ui/primitives/email-field/emails";
import { Input } from "@rhs-ui/primitives/input";
import { cn } from "@/lib/utils";

export interface EmailFieldProps extends Omit<ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "type" | "name"> {
  /** The address, when you control it. It is the clean form (trimmed, domain in lower case) that `onValueChange` reports. */
  value?: string;
  /** The address to start with, when you do not control it. */
  defaultValue?: string;
  /** Called on every change with the address as it will be used and whether it is complete and well formed. */
  onValueChange?: (email: string, state: { valid: boolean }) => void;
  /** The providers a mistyped domain is compared with, in lower case. Default: the common ones (Gmail, Outlook, iCloud, Yahoo and some regional ones). */
  domains?: readonly string[];
  /** Offer the likely fix when the domain looks like a typo of one in `domains`. Default true. */
  suggest?: boolean;
  /** The field's name for a plain form submit. The clean address goes out in a hidden input, so pressing Enter sends what `onValueChange` reported. */
  name?: string;
}

interface Feedback {
  error: string | null;
  suggestion: string | null;
  invalid: boolean;
}

const NONE: Feedback = { error: null, suggestion: null, invalid: false };

/**
 * An email field that catches the typo before it costs a signup. It trims what
 * is typed and lowercases the domain, and `onValueChange` reports that clean
 * address. When the domain is one or two edits from a common provider
 * ("gmial.com"), a quiet line under the field offers the fix as a button,
 * "Use rick@gmail.com instead". Nothing shows while typing: the line appears
 * when the field is left, never blocks a submit, and sits in a polite live
 * region, with the button in the tab order, so a keyboard or screen reader user
 * gets the same help. A malformed address is explained in words ("An address
 * needs an @"), also on leaving the field and then live until it is right.
 */
export function EmailField({ value, defaultValue = "", onValueChange, domains = DEFAULT_EMAIL_DOMAINS, suggest = true, name, form, className, onBlur, "aria-describedby": describedBy, ref, ...props }: EmailFieldProps) {
  const messageId = useId();
  const input = useRef<HTMLInputElement | null>(null);
  // The field keeps the ref you pass and uses its own to put the focus back after a suggestion is taken.
  const attach = useCallback(
    (node: HTMLInputElement | null) => {
      input.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );
  const [draft, setDraft] = useState(value ?? defaultValue);
  const [synced, setSynced] = useState(value);
  const [feedback, setFeedback] = useState<Feedback>(NONE);
  const [said, setSaid] = useState("");

  // A value that arrives from outside replaces what is typed, unless it is only the clean form of it.
  if (value !== undefined && value !== synced) {
    setSynced(value);
    if (value !== normalizeEmail(draft)) setDraft(value);
  }

  useEffect(trackPress, []);

  // What a screen reader was told stays only while it is news; left in the live region it would be read again together with the next message.
  useEffect(() => {
    if (!said) return;
    const timer = window.setTimeout(() => setSaid(""), 4000);
    return () => window.clearTimeout(timer);
  }, [said]);

  function report(text: string) {
    const email = normalizeEmail(text);
    onValueChange?.(email, { valid: isValidEmail(email) });
  }

  function change(event: ChangeEvent<HTMLInputElement>) {
    const text = event.target.value;
    const email = normalizeEmail(text);
    setDraft(text);
    setSaid("");
    // A message that is already showing follows the typing and goes as soon as the address is right. A new one waits for the field to be left.
    setFeedback((now) => (now.error ? { error: describeEmail(email), suggestion: null, invalid: describeEmail(email) !== null } : NONE));
    report(text);
  }

  function leave(event: FocusEvent<HTMLInputElement>) {
    onBlur?.(event);
    const email = normalizeEmail(draft);
    if (email !== draft) setDraft(email);
    whenReleased(() => {
      const problem = describeEmail(email);
      const suggestion = suggest ? suggestEmail(email, domains) : null;
      setFeedback(suggestion ? { error: null, suggestion, invalid: problem !== null } : { error: problem, suggestion: null, invalid: problem !== null });
    });
  }

  function accept() {
    const next = feedback.suggestion;
    if (!next) return;
    setDraft(next);
    setFeedback(NONE);
    setSaid(`Email changed to ${next}.`);
    report(next);
    input.current?.focus();
  }

  return (
    <div data-slot="email-field" className={cn("grid w-full", className)}>
      <Input
        ref={attach}
        type="email"
        inputMode="email"
        autoComplete="email"
        autoCapitalize="none"
        autoCorrect="off"
        spellCheck={false}
        form={form}
        {...props}
        value={draft}
        onChange={change}
        onBlur={leave}
        aria-invalid={feedback.invalid || undefined}
        aria-describedby={[describedBy, messageId].filter(Boolean).join(" ")}
      />
      <div id={messageId} aria-live="polite">
        {feedback.suggestion ? (
          <p className="mt-1.5 flex flex-wrap items-baseline gap-x-1.5 gap-y-0.5 text-xs text-muted-foreground">
            <span>Looks like a typo.</span>
            <button
              type="button"
              onClick={accept}
              className="-mx-0.5 rounded-sm px-0.5 text-left font-medium text-foreground underline decoration-foreground/30 underline-offset-4 transition-colors duration-150 outline-none [overflow-wrap:anywhere] hover:decoration-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40"
            >
              Use {feedback.suggestion} instead
            </button>
          </p>
        ) : feedback.error ? (
          <p className="mt-1.5 flex items-start gap-1.5 text-xs text-destructive">
            <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
            {feedback.error}
          </p>
        ) : null}
        {said ? <span className="sr-only">{said}</span> : null}
      </div>
      {name ? <input type="hidden" name={name} form={form} value={normalizeEmail(draft)} disabled={props.disabled} /> : null}
    </div>
  );
}

/**
 * The providers most addresses end in. A typo in one of these is a lost
 * signup, so they are what a domain is compared with. The list is a prop of
 * EmailField: swap in the domains your own users have.
 */
export const DEFAULT_EMAIL_DOMAINS: readonly string[] = [
  "gmail.com",
  "googlemail.com",
  "outlook.com",
  "hotmail.com",
  "live.com",
  "msn.com",
  "yahoo.com",
  "icloud.com",
  "me.com",
  "mac.com",
  "aol.com",
  "proton.me",
  "protonmail.com",
  "pm.me",
  "gmx.com",
  "gmx.net",
  "gmx.de",
  "web.de",
  "t-online.de",
  "hotmail.de",
  "yahoo.de",
  "zoho.com",
  "hey.com",
  "fastmail.com",
  "mail.com",
  "hotmail.nl",
  "live.nl",
  "outlook.nl",
  "ziggo.nl",
  "kpnmail.nl",
  "planet.nl",
  "hotmail.be",
  "live.be",
  "telenet.be",
  "skynet.be",
  "orange.fr",
  "free.fr",
  "wanadoo.fr",
  "hotmail.fr",
  "yahoo.fr",
  "hotmail.co.uk",
  "yahoo.co.uk",
  "btinternet.com",
  "sky.com",
];

/**
 * How many single-character edits turn one string into the other: an
 * insertion, a deletion, a changed character, or two neighbours swapped
 * (gmial is one edit away, not two). Use it for any "did you mean" of your own.
 */
export function editDistance(a: string, b: string): number {
  const x = [...a];
  const y = [...b];
  let beforePrevious: number[] = [];
  let previous: number[] = Array.from({ length: y.length + 1 }, (_, column) => column);
  for (let row = 1; row <= x.length; row += 1) {
    const current: number[] = [row];
    for (let column = 1; column <= y.length; column += 1) {
      const cost = x[row - 1] === y[column - 1] ? 0 : 1;
      let best = Math.min((previous[column] ?? 0) + 1, (current[column - 1] ?? 0) + 1, (previous[column - 1] ?? 0) + cost);
      if (row > 1 && column > 1 && x[row - 1] === y[column - 2] && x[row - 2] === y[column - 1]) best = Math.min(best, (beforePrevious[column - 2] ?? 0) + 1);
      current.push(best);
    }
    beforePrevious = previous;
    previous = current;
  }
  return previous[y.length] ?? 0;
}

/** The address as it will be used: surrounding spaces gone and the domain in lower case (the part before the @ is left as typed). */
export function normalizeEmail(value: string): string {
  const email = value.trim();
  const at = email.lastIndexOf("@");
  return at === -1 ? email : `${email.slice(0, at)}@${email.slice(at + 1).toLowerCase()}`;
}

const LABEL = "[\\p{L}\\p{N}](?:[\\p{L}\\p{N}-]*[\\p{L}\\p{N}])?";
const ADDRESS = new RegExp(`^[^\\s@]+@(?:${LABEL}\\.)+\\p{L}[\\p{L}\\p{N}-]*[\\p{L}\\p{N}]$`, "u");

/** What is wrong with an address, in a sentence, or null when it is well formed. An empty value is not an error here. */
export function describeEmail(value: string): string | null {
  const email = value.trim();
  if (!email) return null;
  if (/\s/.test(email)) return "Remove the spaces from the address.";
  const at = email.indexOf("@");
  if (at === -1) return "An address needs an @, like name@example.com.";
  if (email.indexOf("@", at + 1) !== -1) return "Use a single @ in the address.";
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  if (!local) return "Add the part before the @, like name@example.com.";
  if (!domain) return "Add the domain after the @, like name@example.com.";
  if (local.startsWith(".") || local.endsWith(".") || local.includes("..")) return "The part before the @ cannot start or end with a dot, or hold two in a row.";
  if (!domain.includes(".")) return "The domain needs an ending, like .com.";
  if (!ADDRESS.test(email)) return "That domain does not look right. Check what follows the @.";
  return null;
}

/** True for a complete, well-formed address. */
export function isValidEmail(value: string): boolean {
  return value.trim() !== "" && describeEmail(value) === null;
}

/**
 * The provider a domain was probably meant to be, or null. A known domain is
 * never "fixed". The name (gmail) and the ending (com) are compared apart: the
 * name may be one edit off (two once it is a long word), the ending one edit
 * off, and never more than two edits together. A short name (aol, msn) is
 * only ever fixed in its ending, because one edit apart is not a typo between
 * two three-letter names: bol.com is not aol.com. A missing dot (gmailcom) is
 * put back.
 */
export function closestDomain(domain: string, domains: readonly string[] = DEFAULT_EMAIL_DOMAINS): string | null {
  const typed = domain.trim().toLowerCase();
  if (!typed || domains.includes(typed)) return null;
  const [typedName = "", ...typedEnding] = typed.split(".");
  let best: string | null = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const candidate of domains) {
    const [name = "", ...ending] = candidate.split(".");
    let distance: number;
    if (typedEnding.length === 0) {
      distance = typed === candidate.replace(/\./g, "") ? 1 : Number.POSITIVE_INFINITY;
    } else {
      const nameDistance = editDistance(typedName, name);
      const endingDistance = editDistance(typedEnding.join("."), ending.join("."));
      const nameLimit = name.length <= 3 ? 0 : Math.min(typedName.length, name.length) >= 8 ? 2 : 1;
      distance = nameDistance <= nameLimit && endingDistance <= 1 && nameDistance + endingDistance <= 2 ? nameDistance + endingDistance : Number.POSITIVE_INFINITY;
    }
    if (distance < bestDistance) {
      best = candidate;
      bestDistance = distance;
    }
  }
  return best;
}

/** The whole address with a mistyped domain put right ("rick@gmial.com" gives "rick@gmail.com"), or null when there is nothing to offer. */
export function suggestEmail(value: string, domains: readonly string[] = DEFAULT_EMAIL_DOMAINS): string | null {
  const email = normalizeEmail(value);
  const at = email.lastIndexOf("@");
  if (at < 1 || /\s/.test(email) || email.indexOf("@") !== at) return null;
  const closest = closestDomain(email.slice(at + 1), domains);
  return closest ? `${email.slice(0, at)}@${closest}` : null;
}

// A message that appears while a finger or a mouse button is still down moves the next control from under the pointer and swallows its click (the usual way
// a blur check eats a submit), so such a message waits until the press is over.
//
// A mouse press moves the focus while the button is down. A touch tap does not: it runs pointerdown, touchstart, pointerup, touchend, and only then the mouse
// events the browser makes up (mousedown, which moves the focus and blurs the field, then mouseup and click). So a press is armed by pointerdown, mousedown and
// touchstart alike, and a release only counts when no newer press began after it was announced.

/** A press that began longer ago than this is taken to be stuck (its release never arrived), not to be the one that blurred the field. */
const STALE_MS = 3000;

let pressed = false;
let pressedAt = 0;
let presses = 0;
let tracking = false;
const afterRelease: (() => void)[] = [];

/** Starts watching presses for the whole page, once. Call it from an effect. */
export function trackPress(): void {
  if (tracking) return;
  tracking = true;
  const press = () => {
    pressed = true;
    pressedAt = performance.now();
    presses += 1;
  };
  const release = () => {
    const seen = presses;
    window.setTimeout(() => {
      // Touch makes its mouse events after it has released: a press that began since then is still going on.
      if (seen !== presses) return;
      pressed = false;
      for (const run of afterRelease.splice(0)) run();
    }, 0);
  };
  // Passive: these only watch, and a touch listener that could cancel would hold the page's scrolling back.
  const options = { capture: true, passive: true };
  for (const type of ["pointerdown", "mousedown", "touchstart"] as const) document.addEventListener(type, press, options);
  for (const type of ["pointerup", "pointercancel", "mouseup", "touchend", "touchcancel", "click"] as const) document.addEventListener(type, release, options);
}

/** Runs `run` now, or, while a press is going on, as soon as it is over. */
export function whenReleased(run: () => void): void {
  if (pressed && performance.now() - pressedAt < STALE_MS) afterRelease.push(run);
  else run();
}
